import { useEffect,useState } from 'react'
import { Link } from 'react-router-dom'
import api from '../../services/api'
import LoadingSpinner from '../../components/LoadingSpinner'
export default function VendorProducts(){const [items,setItems]=useState(null);const load=()=>api.get('/api/vendor/products').then(({data})=>setItems(data));useEffect(load,[]);async function disable(id){await api.delete(`/api/vendor/products/${id}`);load()}if(!items)return <LoadingSpinner/>;return <><div className="vendor-heading"><div><span className="section-kicker">Catalog management</span><h1 className="vendor-title">Vendor Products</h1></div><Link className="auth-submit" to="/vendor/products/new">+ Add Product</Link></div><div className="vendor-table">{items.length?items.map(item=><div className="vendor-row" key={item.id}><span><strong>{item.name}</strong><small>{item.category}</small></span><b>₹{item.price}</b><span>{item.stock_quantity}</span><span>{item.is_available?'Available':'Disabled'}</span><span><Link to={`/vendor/products/${item.id}/edit`}>Edit</Link>{item.is_available&&<button onClick={()=>disable(item.id)}>Disable</button>}</span></div>):<p>No products yet.</p>}</div></>}
